package com.conferbot.sdk.core.customization

/**
 * The web widget's 27 themes, as data: surfaces and text per scheme, the
 * shape (radii, bubble outline), the theme font and its palette. Generated
 * from conferbot-widget src/css/themes/<id>.css and src/ts/theme/palettes.json
 * (registry.ts order). Colours are hex / rgb(a), or "mix:N:<colour>" (N% of
 * the bot's brand over that colour) and "accent:<alpha>" (the brand lifted
 * for dark surfaces). Do not edit by hand.
 */
internal data class ThemeShapeData(
    val rBubble: Float?, val rTail: Float?, val rCtl: Float?, val rField: Float?, val rCard: Float?,
    val bubbleBorderWidth: Float, val bubbleBorderColor: String?, val displayWeight: Int,
)

internal data class ThemeData(
    val label: String,
    val font: String?,
    val fontRole: String?,
    val alwaysDark: Boolean,
    val shape: ThemeShapeData?,
    val light: Map<String, String>?,
    val dark: Map<String, String>,
    val paletteLight: Map<String, String>?,
    val paletteDark: Map<String, String>?,
)

